from edition.scripts.root_audit import Audit

a=Audit(122)
a.keep('B01','The upper number has the closed lower bowl of 6 followed by 0. The T decoration is a tall separate stroke with its own lower dot, hence !; only script order and the page wrapper differ.')
a.keep('B02','The D has a detached upright and dot above its lower d. In lequel the tall l precedes the short final cluster; there is no extra feminine ending.')
a.keep('B03','The group sign has a broad outer curve and a separate inward returning S-shaped stroke; it differs from the ordinary G elsewhere on this leaf. The first fraktur-S rendering is retained.')
a.keep('B04','The canceled short word retains a left shoulder, low medial rise and final v-like turn, supporting tentative rev. The cancellation prevents certainty about all letters; the separate point is visible.')
f=a.comparison['B05']['first'].removesuffix('.')
a.change('B05',f,'The relation has two distinct wavy strokes above a straight lower bar, confirming approxeq. The outer closing parenthesis runs into the scan edge, with no independently visible following point; an off-image point is not supplied.')
a.replace(a.comparison['B05']['first'],f)
a.add_row('B05','Point after the outer parenthesis ending the first sentence',r'$D_d$).',r'$D_d$).',r'$D_d$)', 'medium','punctuation','supplied punctuation',True,True)
a.keep('B06','The high D mark has its own dot below the upright, and the d before morphismes is raised above the baseline as an insertion. No independent word discrepancy remains.')
a.keep('B07','The label is an open upper s curve with a small lower returning loop and separate subscript i, as in (187). The shaft ends in a short downward turn without a second converging barb. Both lower inequality strokes, the source bang and label (185) are visible.')
a.keep('B08','The group glyph has the same broad outer curve and inner returning S form seen in B03 and B19; the blind G alternative is not preferred from this ink.')
a.keep('B09','The horizontal shaft ends in a short downward turn, not a full two-barbed head. The labels D_1 and D_0 and the following est une are clear; the literal connector remains.')
a.keep('B10','The stroke below régulière runs only beneath its beginning and returns through the g descender, rather than underlining the whole word. The raised de codim 1 and its bent attachment stroke are visible; math delimiters around 1 do not change the reading.')
a.keep('B11','The cancellation crosses the lower le and the compressed noun, while sur D_1 is raised within that revision. The long descender and following short dotted strokes support tentative faisceau, but no distinct additional inv. can be separated. The terminal point is visible and the uncertain noun is retained.')
a.keep('B12','The label reads (186), followed by L with subscript 1. The words faisceau inversible occupy the upper line and canonique sur D_1 the lower line; the difference is layout encoding.')
a.keep('B13','The decoration consists of a long nearly upright stroke with a small hooked entry and a separate lower dot. There is no broad question-mark bowl; the repeated ! form is retained.')
a.keep('B14','The open upper curve and small returning lower loop of s match B07; there is no independently closed delta body. The star, both subscripts, equality, two weak lower inequality bars and final point are visible.')
a.keep('B15','The G has a doubled inner stroke, with m at its lower right; the parenthesized group carries D_d still lower. The additional word torseurs in the second box is already present in the page text.')
f=r'(18\unsure{8|3})'
a.change('B16',f,'The final digit has a closed lower loop and a narrow almost vertical upper trace, making 8 the leading reading. Its upper loop is not securely separated, so the blind alternative 3 remains possible; the preceding 1 and 8 are clear.')
a.replace('(188)',f)
a.add_row('B16','Final digit of display label following (187)','(188)','(188)',f,'medium','number','ambiguous numeral',True,True)
a.doubt('Final digit of display label following (187)',f,'8 leads because of the lower loop and upper return; 3 cannot be excluded because the upper portion is compressed. No sequential-number argument is used.','medium')
a.keep('B17','The L is underlined and starred, with d,i below. The doubled G carries m and then D_d below that level, whereas the later base is simply D_d. The two descriptive lines and abbreviation inv. are visible; braces and font encoding account for the difference.')
a.keep('B18','The P has a detached bang, the product has lower bounds 1 to d, and L is underlined and starred. The right G has m below and d above, with no following point visible. The differences are wrappers, font and script order.')
a.keep('B19','The broad S-shaped group sign is distinct from G. The verb has the final rising t of opérant, followed by a D with detached bang and the clearly written permute les; the literal grammatical construction is retained.')
f=r'\inserted{$\unsure{s_i|\delta_i}$ donc les} $\underline L_{d,i}$ entre'
a.change('B20',f,'The raised label has an open upper curl but a dark retraced lower loop and an additional left stroke. The clearer s forms in B07 and B14 favor s_i, while this occurrence alone also permits delta_i. The insertion curve, donc les and underlined L are clear.')
a.replace(a.comparison['B20']['first'],f)
a.add_row('B20','Raised morphism label in the last paragraph',r'\inserted{$s_i$ donc les}',r'\add{$s_i$ donc les}',r'\inserted{$\unsure{s_i|\delta_i}$ donc les}','medium','letter','ambiguous overtrace',True,True,True)
a.doubt('Raised morphism label in the last paragraph',r'\unsure{s_i|\delta_i}','s_i is supported by the clearer labels in (185) and (187); the doubled lower loop in this raised occurrence also permits delta_i.','medium')
a.keep('B21','The canceled word preserves the q bowl and long descender, a u shoulder and a separate final i dot. The raised de is clear; cancellation does not obscure enough of these three letters to require a new uncertainty marker.')
a.keep('B22','The canceled word retains the initial d loop and ascender, the low e-v joins, a separate i dot, and the final tall t with cross-stroke. These support devient despite the horizontal strike; façon begins separately at the right.')
a.keep('B23','The pencil number has two upright 1 strokes around the curved-top, sloping and basal 2. The margin wrapper is the only difference.')
for e in a.report['inventory']:
 if e['element']=='E18':e['first_words_or_objects']=e['first_words_or_objects'].replace('(188)',r'(18\unsure{8|3})')
 if e['element']=='E22':e['first_words_or_objects']=r'\inserted{$\unsure{s_i|\delta_i}$ donc les}'
a.note('Blind audit: all 23 differing boxes were inspected in their fresh crops. The edge-adjacent point after the first parenthesis was removed, the final digit of the (188) label retains 8|3, and the retraced raised morphism label retains s_i|delta_i. The clearer labels in (185) and (187), the two-wave relation, partial under-stroke, literal group bases and one-sided connectors were retained from ink. No mathematical completion supplied missing marks.')
a.finish()
